package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.special.Erf;
import org.apache.commons.math3.exception.MathException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NormalDistributionImpl#inverseCumulativeProbability
 */
public class NormalDistributionImpl_inverseCumulativeProbability_TriageGen0Test {

    private NormalDistributionImpl distribution;
    private static final double DELTA = 1e-10;

    @Before
    public void setUp() {
        // Standard normal distribution (mean=0, sd=1)
        distribution = new NormalDistributionImpl(0.0, 1.0);
    }

    @Test
    public void testInverseCumulativeProbability_PZero() throws MathException {
        double p = 0.0;
        double expected = Double.NEGATIVE_INFINITY;
        double actual = distribution.inverseCumulativeProbability(p);
        Assert.assertEquals("When p is 0, result should be Double.NEGATIVE_INFINITY", expected, actual, 0.0);
    }

    @Test
    public void testInverseCumulativeProbability_POne() throws MathException {
        double p = 1.0;
        double expected = Double.POSITIVE_INFINITY;
        double actual = distribution.inverseCumulativeProbability(p);
        Assert.assertEquals("When p is 1, result should be Double.POSITIVE_INFINITY", expected, actual, 0.0);
    }

    @Test
    public void testInverseCumulativeProbability_StandardValues() throws MathException {
        // Test p = 0.5 (Median of standard normal is mean)
        double p05 = 0.5;
        double expected05 = 0.0;
        double actual05 = distribution.inverseCumulativeProbability(p05);
        Assert.assertEquals("When p is 0.5, result should be the mean (0.0)", expected05, actual05, DELTA);

        // Test p = 0.8413447 (approx 1 sigma)
        double p84 = 0.8413447460685429;
        double expected84 = 1.0;
        double actual84 = distribution.inverseCumulativeProbability(p84);
        Assert.assertEquals("When p is approx 0.8413, result should be approx 1.0", expected84, actual84, 1e-7);
    }

    @Test
    public void testInverseCumulativeProbability_CustomMeanAndSD() throws MathException {
        // Custom distribution: mean=10, sd=2
        NormalDistributionImpl customDist = new NormalDistributionImpl(10.0, 2.0);
        double p = 0.5;
        double expected = 10.0;
        double actual = customDist.inverseCumulativeProbability(p);
        Assert.assertEquals("Result should respect custom mean", expected, actual, DELTA);
    }

    @Test(expected = MathException.class)
    public void testInverseCumulativeProbability_InvalidP_Low() throws MathException {
        // Depending on implementation, p < 0 might throw MathException via super
        // This tests the branch that goes to super.inverseCumulativeProbability
        distribution.inverseCumulativeProbability(-0.1);
    }

    @Test(expected = MathException.class)
    public void testInverseCumulativeProbability_InvalidP_High() throws MathException {
        // Depending on implementation, p > 1 might throw MathException via super
        distribution.inverseCumulativeProbability(1.1);
    }
}
